```c++
#include <DHT.h>

#define DHT_PIN 2  // Pin number for DHT22 connection

DHT dht(DHT_PIN, DHT22);

void setup() {
  Serial.begin(9600);
  dht.begin();
}

void loop() {
  int count = 0;
  float sumTemperature = 0;
  float sumHumidity = 0;

  while (count < 100) {  // Take 100 readings
    float temperature = dht.readTemperature();
    float humidity = dht.readHumidity();

    sumTemperature += temperature;
    sumHumidity += humidity;

    delay(50); // Wait 50ms between readings
    count++;
  }

  float averageTemperature = sumTemperature / count;
  float averageHumidity = sumHumidity / count;

  Serial.print("Calibration Results: ");
  Serial.print("Temperature: ");
  Serial.print(averageTemperature);
  Serial.print("°C, ");
  Serial.print("Humidity: ");
  Serial.print(averageHumidity);
  Serial.println("%");

  // Save the calibration values to EEPROM
  EEPROM.put(0, averageTemperature);
  EEPROM.put(4, averageHumidity);
  EEPROM.commit();

  delay(10000); // Wait 10 seconds before restarting the sketch
  restartSketch();
}

void restartSketch() {
  asm("  jmp 0");
}
```
