const canvas = document.getElementById('pendulum-canvas');
const ctx = canvas.getContext('2d');

// Pendulum parameters
const GRAVITY = 9.81; // m/s^2
const LENGHT = 100; // cm
const MASS = 1; // kg

// Initial parameters
let initialAngle = 30; // degrees
let released = false;

// Function to update the pendulum's position and angle
function updatePendulum() {
  if (!released) return;

  const theta = initialAngle * Math.PI / 180; // Convert degrees to radians
  const omega = 0; // initial angular velocity
  const gamma = GRAVITY / LENGHT;

  // Update angular velocity
  omega += gamma * Math.sin(theta);

  // Update angle
  theta += omega;

  // Update x and y coordinates
  const x = LENGHT * Math.sin(theta);
  const y = -LENGHT * Math.cos(theta);

  // Draw the pendulum
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.beginPath();
  ctx.arc(canvas.width / 2, canvas.height / 2, LENGHT / 2, 0, 2 * Math.PI);
  ctx.fillStyle = '#ccc';
  ctx.fill();
  ctx.beginPath();
  ctx.arc(canvas.width / 2 + x, canvas.height / 2 - y, LENGHT / 5, 0, 2 * Math.PI);
  ctx.fillStyle = '#333';
  ctx.fill();

  // Check if the pendulum has stopped
  if (Math.abs(omega) < 0.01) {
    released = false;
  }

  // Request the next update
  requestAnimationFrame(updatePendulum);
}

